def radar_layer(start, end, name):
    """One pass in dB, land made transparent (the basemap shows the coast), on the shared grey scale."""
    db = one_pass(start, end).apply(lambda x: x.log(10) * 10)
    sea = db.process("mask_polygon", data=db, mask=LAND, inside=True)
    colored = sea.process("colormap", data=sea, colormap=DB_COLORMAP)
    add_graph_to_map(colored.save_result("PNG"), name)


OPEN_ON = 0
radar_layer("2018-10-08T17:20:00Z", "2018-10-08T17:24:00Z", "8 Oct eve · slick ~35 km")
radar_layer("2018-10-09T17:09:00Z", "2018-10-09T17:19:00Z", "9 Oct eve · slick 50–60 km")
radar_layer("2018-10-13T05:35:40Z", "2018-10-13T05:36:30Z", "13 Oct · fragments, oil?")

# Studio draws every visible layer, later ones on top and semi-transparent (80 %, 70 %, ...), so two
# ticked layers blend: open on ONE layer and untick it before ticking the next (hidden layers fetch no
# tiles until ticked).
for i, g in enumerate(map_graphs):
    g["visible"] = i == OPEN_ON
